if(!window.ROSTER_DATA){document.body.innerHTML='<main style="font:16px Arial;padding:40px;max-width:700px"><h1>Roster data is unavailable</h1><p>Keep the supplied Excel roster available on this computer and ask Codex to refresh the prototype data package.</p></main>';throw new Error('Roster data file unavailable')}
const D=window.ROSTER_DATA, H=D.households, PAGE=50;
const state={view:'overview',page:1,q:'',barangay:'',status:'',set:'',caseFlag:'',memberPage:1,memberQ:'',selected:null};
