  fillSelect('barangayFilter',uniq(H.map(h=>h[4])),'All barangays');fillSelect('statusFilter',uniq(H.map(h=>h[2])),'All statuses');fillSelect('setFilter',uniq(H.map(h=>h[1])),'All sets');
  renderOverview();renderHouseholds();renderMembers();renderCases();renderReports();$('csrDate').value=new Date().toISOString().slice(0,10);$('healthDate').value=new Date().toISOString().slice(0,10);$('busDate').value=new Date().toISOString().slice(0,10);$('schoolDate').value=new Date().toISOString().slice(0,10);showView('overview');
