function fillSelect(id,values,label){$(id).innerHTML=`<option value="">${label}</option>`+values.map(v=>`<option>${esc(v)}</option>`).join('')}
function showView(v){state.view=v;document.querySelectorAll('.view').forEach(x=>x.classList.toggle('active',x.id===`view-${v}`));document.querySelectorAll('.nav button').forEach(x=>x.classList.toggle('active',x.dataset.view===v));const titles={overview:['Operations overview','Monitor roster coverage and follow-up priorities.'],households:['Household directory','Search, filter and review all registered households.'],members:['Member directory','Find any roster member and open their household profile.'],cases:['Case management queue','Prioritize households requiring validation or follow-up.'],reports:['Analyst reports','Explore barangay and program-status distributions.'],csr:['CSR Generator','Create a roster-populated Social Case Study Report for case-manager validation.'],health:['Health Certificate','Generate a grantee-only Health Center/Station Enrolment Certificate.'],school:['School Certificate','Generate a grantee-level School Enrolment Certificate with blank learner rows.'],bus:['BUS Form 5','Prepare a Beneficiary Data Update Request using roster-backed household details.']};$('pageTitle').textContent=titles[v][0];$('pageSub').textContent=titles[v][1];window.scrollTo({top:0,behavior:'smooth'})}
function renderOverview(){
 const active=Object.entries(D.meta.statuses).find(([k])=>/^1 - Active/i.test(k))?.[1]||0, flags=H.filter(h=>h[6].length).length, children=H.reduce((a,h)=>a+h[7].filter(m=>m[5]&&m[5]!=='NO').length,0);
 $('kpis').innerHTML=[['Registered households',D.meta.households,'Complete roster'],['Active households',active,`${Math.round(active/D.meta.households*100)}% of households`],['Family members',D.meta.members,`${(D.meta.members/D.meta.households).toFixed(1)} average`],['Child beneficiaries',children,'Across monitored households']].map((x,i)=>`<article class="kpi"><label>${x[0]}</label><i>${i===3?'CVS':'May 2026'}</i><strong>${fmt(x[1])}</strong><small>${x[2]}</small></article>`).join('');
 const entries=Object.entries(D.meta.statuses).sort((a,b)=>b[1]-a[1]),max=entries[0][1];$('statusBars').innerHTML=entries.map(([s,n])=>`<div class="status-row"><span title="${esc(s)}">${esc(s.replace(/^\d+\s*-\s*/,''))}</span><div class="bar"><i style="width:${n/max*100}%"></i></div><b>${fmt(n)}</b></div>`).join('');
 const qs=[['Flagged households',flags,'','cases'],['Grants temporarily on-hold',countStatus('hold'),'On hold','cases'],['Unlocated / moved households',countStatus('unlocated|moved'),'Locate / validate','cases'],['For NPMO processing',countStatus('processing'),'For processing','cases']];$('priorityQueue').innerHTML=qs.map(q=>`<button onclick="openQueue('${q[2]}')"><span><b>${q[0]}</b><small>Open household worklist</small></span><strong>${fmt(q[1])} ›</strong></button>`).join('')}
function countStatus(pattern){const r=new RegExp(pattern,'i');return H.filter(h=>r.test(h[2])).length}
function filteredH(){const q=state.q.toLowerCase();return H.filter(h=>(!state.barangay||h[4]===state.barangay)&&(!state.status||h[2]===state.status)&&(!state.set||h[1]===state.set)&&(!state.caseFlag||h[6].includes(state.caseFlag))&&(!q||`${h[0]} ${h[1]} ${h[2]} ${h[3]} ${h[4]} ${h[5]} ${h[7].map(m=>m[0]).join(' ')}`.toLowerCase().includes(q)))}
function applyFilters(){state.q=$('hhSearch').value;state.barangay=$('barangayFilter').value;state.status=$('statusFilter').value;state.set=$('setFilter').value;state.page=1;renderHouseholds()}
function resetFilters(){state.q=state.barangay=state.status=state.set=state.caseFlag='';$('hhSearch').value='';['barangayFilter','statusFilter','setFilter'].forEach(id=>$(id).value='');state.page=1;renderHouseholds()}
