function renderCases(){const types={};H.forEach(h=>h[6].forEach(f=>types[f]=(types[f]||0)+1));$('caseCards').innerHTML=Object.entries(types).sort((a,b)=>b[1]-a[1]).map(([f,n])=>`<article class="case-card" onclick="openQueue('${esc(f)}')"><small>${esc(f)}</small><strong>${fmt(n)}</strong><small>households · Open queue →</small></article>`).join('')||'<div class="empty">No derived case flags found.</div>';renderCaseTable()}
function renderCaseTable(){const list=H.filter(h=>h[6].length&&(!state.caseFlag||h[6].includes(state.caseFlag)));$('caseQueueTitle').textContent=state.caseFlag||'All flagged households';$('caseRows').innerHTML=list.slice(0,500).map(h=>`<tr onclick="openProfile('${h[0]}','case')"><td><b>${esc(hhName(h))}</b><small>${esc(h[0])}</small></td><td>${esc(h[4])}</td><td>${h[6].map(f=>`<span class="pill warn">${esc(f)}</span>`).join(' ')}</td><td>${esc(h[2])}</td><td>${localCase(h[0]).priority||'Not set'}</td><td>›</td></tr>`).join('')||'<tr><td colspan="6" class="empty">No households in this queue.</td></tr>'}
function openQueue(flag){state.caseFlag=flag;showView('cases');renderCaseTable()}
function renderReports(){const barangays=Object.entries(D.meta.barangays).sort((a,b)=>b[1]-a[1]),max=barangays[0][1];$('barangayReport').innerHTML=barangays.map(([b,n])=>`<div class="report-item"><b>${esc(b)}</b><strong>${fmt(n)}</strong><div class="bar"><i style="width:${n/max*100}%"></i></div></div>`).join('');$('statusReport').innerHTML=Object.entries(D.meta.statuses).sort((a,b)=>b[1]-a[1]).map(([s,n])=>`<div class="report-item"><b>${esc(s.replace(/^\d+\s*-\s*/,''))}</b><strong>${fmt(n)}</strong><div class="bar"><i style="width:${n/D.meta.households*100}%"></i></div></div>`).join('')}
function localCase(id){try{return JSON.parse(localStorage.getItem(`sf-case-${id}`)||'{}')}catch{return {}}}
function openProfile(id,pane='members'){const h=H.find(x=>x[0]===id);if(!h)return;state.selected=h;$('profileTitle').textContent=hhName(h);$('profileMeta').textContent=`HH ${h[0]} · ${h[4]} · Set ${h[1]} · Cluster ${h[3]}`;$('profileSummary').innerHTML=[['Grantee',h[5]||'Not tagged'],['Program status',h[2]],['Members',h[7].length],['Case flags',h[6].length||'None'],['Barangay',h[4]]].map(x=>`<div><small>${x[0]}</small><b>${esc(x[1])}</b></div>`).join('');$('profileMembers').innerHTML=h[7].map(m=>`<div class="member-row"><div><b>${esc(m[0])}</b><small>${esc(m[4])}</small></div><div>${esc(m[1])}</div><div>${esc(m[2])}</div><div class="hide-mobile">${esc(m[3])}</div><div class="hide-mobile">${esc(m[5]&&m[5]!=='NO'?'Child beneficiary':'Member')}</div></div>`).join('');$('profileFlags').innerHTML=h[6].map(f=>`<span class="pill warn">${esc(f)}</span>`).join(' ')||'<p class="empty">No derived follow-up flags for this household.</p>';const c=localCase(id);$('casePriority').value=c.priority||'';$('caseOwner').value=c.owner||'';$('caseStatus').value=c.status||'Open';$('caseNotes').value=c.notes||'';$('saveStatus').textContent='';showProfilePane(pane);$('profileModal').classList.add('open');document.body.style.overflow='hidden'}
function closeProfile(){$('profileModal').classList.remove('open');document.body.style.overflow=''}function showProfilePane(p){document.querySelectorAll('.profile-pane').forEach(x=>x.classList.toggle('active',x.id===`profile-${p}`));document.querySelectorAll('.tabs button').forEach(x=>x.classList.toggle('active',x.dataset.pane===p))}
function saveCase(){if(!state.selected)return;localStorage.setItem(`sf-case-${state.selected[0]}`,JSON.stringify({priority:$('casePriority').value,owner:$('caseOwner').value,status:$('caseStatus').value,notes:$('caseNotes').value,updated:new Date().toISOString()}));$('saveStatus').textContent='Saved locally';renderCaseTable()}
function exportHouseholds(){const list=filteredH(),rows=[['HH_ID','Grantee','Barangay','Set','Cluster','Status','Members','Flags'],...list.map(h=>[h[0],h[5],h[4],h[1],h[3],h[2],h[7].length,h[6].join('; ')])];downloadCsv('san-fabian-households.csv',rows)}
