function downloadCsv(name,rows){const csv=rows.map(r=>r.map(v=>`"${String(v??'').replaceAll('"','""')}"`).join(',')).join('\r\n'),a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv'}));a.download=name;a.click();URL.revokeObjectURL(a.href)}
function ensureHealthView(){const view=document.createElement('section');view.className='view';view.id='view-health';view.innerHTML=`<div class="health-layout"><aside class="panel health-form"><div><h2>Health Enrolment Certificate</h2><p class="sub">A4 form · two certificate copies</p></div><div><label>Household ID number</label><div class="toolbar"><input id="healthHhid" placeholder="Enter complete or partial HHID"><button class="btn primary" onclick="findHealthHousehold()">Find</button></div><small id="healthLookupStatus"></small></div><div><label>Name of grantee</label><input id="healthGrantee" readonly></div><div><label>Name of health facility</label><input id="healthFacility" oninput="renderHealthCert()" placeholder="Auto-filled when available; otherwise enter manually"></div><div><label>Facility ID number</label><input id="healthFacilityId" oninput="renderHealthCert()"></div><div><label>Address of health facility</label><input id="healthAddress" oninput="renderHealthCert()"></div><div><label>Type of health facility</label><select id="healthType" onchange="renderHealthCert()"><option value="">Not selected</option><option value="RHU">Rural Health Station (RHU)</option><option value="BHS">Barangay Health Station (BHS)</option></select></div><div><label>Date issued</label><input id="healthDate" type="date" onchange="renderHealthCert()"></div><div><label>Signatory / position</label><input id="healthSignatory" oninput="renderHealthCert()" placeholder="Signature over printed name / position"></div><div class="health-actions"><button class="btn primary" onclick="downloadHealthWord()">Download Word (.doc)</button><button class="btn" onclick="window.print()">Print / Save PDF</button><button class="btn" onclick="clearHealthCert()">Clear</button></div><div class="csr-hint"><b>Privacy rule:</b> This form uses only household ID and grantee-level details. Family-member names and information are intentionally excluded.</div></aside><section class="health-preview"><div class="health-paper" id="healthPaper"><div class="empty">Enter a Household ID to generate the certificate.</div></div></section></div>`;document.querySelector('main.shell').insertBefore(view,document.querySelector('main.shell footer'))}
let healthHousehold=null;
function findHealthHousehold(){const q=$('healthHhid').value.trim().replace(/^#/,'');if(!q){$('healthLookupStatus').textContent='Enter a Household ID.';return}const exact=H.find(h=>h[0]===q),matches=exact?[exact]:H.filter(h=>h[0].includes(q));if(matches.length!==1){$('healthLookupStatus').textContent=matches.length?`${fmt(matches.length)} matches. Enter more digits.`:'No household found.';return}loadHealthHousehold(matches[0])}
function generateHealthForSelected(){if(!state.selected)return;closeProfile();showView('health');$('healthHhid').value=state.selected[0];loadHealthHousehold(state.selected)}
function loadHealthHousehold(h){healthHousehold=h;const normalize=s=>String(s||'').replace(/[^a-z]/gi,'').toLowerCase(),g=h[7].find(m=>normalize(m[0])===normalize(h[5]))||h[7][0],facility=g?.[10]||'';$('healthLookupStatus').textContent=`Found: ${h[5]} · ${h[4]}`;$('healthGrantee').value=h[5];$('healthFacility').value=facility;$('healthAddress').value=`${h[4]}, San Fabian, Pangasinan, Region I`;$('healthFacilityId').value='';$('healthType').value=/barangay|bhs/i.test(facility)?'BHS':/rural|rhu|municipal/i.test(facility)?'RHU':'';renderHealthCert()}
function clearHealthCert(){healthHousehold=null;['healthHhid','healthGrantee','healthFacility','healthFacilityId','healthAddress','healthSignatory'].forEach(id=>$(id).value='');$('healthType').value='';$('healthLookupStatus').textContent='';$('healthPaper').innerHTML='<div class="empty">Enter a Household ID to generate the certificate.</div>'}
function healthCopyHtml(){const h=healthHousehold,type=$('healthType').value,date=$('healthDate').value?new Date($('healthDate').value+'T00:00:00'):new Date(),day=date.getDate(),month=date.toLocaleDateString('en-PH',{month:'long'}),year=date.getFullYear();return `<section class="health-copy"><div class="health-brand"><div class="health-mark">DSWD</div><div><p>Pantawid Pamilyang Pilipino Program</p><h2>HEALTH CENTER/STATION ENROLMENT CERTIFICATE</h2></div><div class="health-mark">4Ps</div></div><div class="health-fields"><label>Household ID No.:</label><div class="health-line">${esc(h[0])}</div><label>Name of Grantee:</label><div class="health-line">${esc(h[5])}</div><label>Name of Health Facility:</label><div class="health-line">${esc($('healthFacility').value)}</div><label>Facility ID Number:</label><div class="health-line">${esc($('healthFacilityId').value)}</div><label>Address of Health Facility:</label><div class="health-line">${esc($('healthAddress').value)}</div></div><div class="facility-types">${type==='RHU'?'◉':'○'} Rural Health Station (RHU)<br>${type==='BHS'?'◉':'○'} Barangay Health Station (BHS)</div><p class="health-cert-text">This is to certify that the following children/pregnant women are enrolled in this Health Facility:</p><table class="health-table"><thead><tr><th rowspan="2">NAME</th><th>REMARKS</th></tr><tr><th><i>Age and Birthday for 0-5 years old or<br>Last Menstrual Period for Pregnant</i></th></tr></thead><tbody><tr><td>&nbsp;</td><td>___ y/o &nbsp; mm/dd/yyyy</td></tr><tr><td>&nbsp;</td><td>___ y/o &nbsp; mm/dd/yyyy</td></tr><tr><td>&nbsp;</td><td>___ y/o &nbsp; mm/dd/yyyy</td></tr></tbody></table><p class="health-given">Given this <u>${day}</u> day of <u>${month}</u>, ${year}.</p><div class="health-sign">${esc($('healthSignatory').value)||'Signature over Printed Name/ Position'}</div></section>`}
function renderHealthCert(){if(!healthHousehold)return;$('healthPaper').innerHTML=healthCopyHtml()+'<div class="health-divider"></div>'+healthCopyHtml()}
function downloadHealthWord(){if(!healthHousehold){$('healthLookupStatus').textContent='Find a household first.';return}renderHealthCert();const css='body{font:9pt Arial}.health-copy{height:5.25in}.health-brand{text-align:center}.health-mark{display:inline-block;border:1px solid #999;padding:4px;float:left}.health-brand h2{font-size:12pt;margin:2px}.health-brand p{margin:0}.health-fields{margin-top:12px}.health-fields label{display:inline-block;width:1.5in}.health-line{display:inline-block;width:5in;border-bottom:1px solid #111}.facility-types{margin:8px 0 10px 1.6in}.health-table{width:100%;border-collapse:collapse;font-size:8pt}.health-table th,.health-table td{border:1px solid #222;padding:3px;text-align:center}.health-given{margin:14px}.health-sign{width:3in;margin:18px 0 0 auto;border-top:1px solid #111;text-align:center}.health-divider{border-top:1px dashed #aaa;margin:8px}',html=`<html xmlns:w="urn:schemas-microsoft-com:office:word"><head><meta charset="utf-8"><style>${css}</style></head><body>${$('healthPaper').innerHTML}</body></html>`,a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff'+html],{type:'application/msword'}));a.download=`Health_Certificate_${healthHousehold[0]}_${(healthHousehold[5]||'Grantee').replace(/[^a-z0-9]+/gi,'_')}.doc`;a.click();URL.revokeObjectURL(a.href)}
let csrHousehold=null;
function findCsrHousehold(){const q=$('csrHhid').value.trim().replace(/^#/,'');if(!q){$('csrLookupStatus').textContent='Enter a Household ID.';return}const exact=H.find(h=>h[0]===q),matches=exact?[exact]:H.filter(h=>h[0].includes(q));if(matches.length!==1){$('csrLookupStatus').textContent=matches.length?`${fmt(matches.length)} matches. Enter more digits.`:'No household found.';return}loadCsr(matches[0])}
function generateCsrForSelected(){if(!state.selected)return;closeProfile();showView('csr');$('csrHhid').value=state.selected[0];loadCsr(state.selected)}
function loadCsr(h){csrHousehold=h;$('csrLookupStatus').textContent=`Found: ${hhName(h)} · ${h[4]} · ${h[7].length} members`;const ages=h[7].map(m=>Number(m[2])).filter(Number.isFinite),children=ages.filter(a=>a<18).length,adults=ages.filter(a=>a>=18&&a<60).length,seniors=ages.filter(a=>a>=60).length,school=h[7].filter(m=>m[6]&&!/^(NO|N\/A)$/i.test(m[6])).length,health=h[7].filter(m=>m[9]&&!/^(NO|N\/A)$/i.test(m[9])).length,flags=h[6].join(', ')||'no automated follow-up flag';$('csrProblem').value=`The household is currently enrolled under ${h[2]}. The roster indicates ${h[7].length} family members, including ${children} member(s) below 18 years old. The case manager should validate the household's current economic situation, immediate needs, and the circumstances related to ${flags}.`;$('csrBackground').value=`The household is registered in Barangay ${h[4]}, San Fabian, Pangasinan, under Set ${h[1]} and Cluster ${h[3]}. ${h[5]} is recorded as the household grantee. The roster lists ${children} child member(s), ${adults} working-age adult member(s), and ${seniors} senior citizen member(s). ${school} member record(s) contain school-attendance information and ${health} contain health-monitoring information. This summary is generated from roster fields and requires confirmation through interview, home visit, and available case records.`;$('csrAssessment').value=`Based solely on the roster, the household remains classified as ${h[2]}. Household composition and available monitoring indicators suggest that continued review should focus on compliance, access to education and health services, and any recorded follow-up flags. No conclusion regarding income, housing condition, livelihood, family functioning, or level of well-being should be made until these are validated by the assigned case manager.`;$('csrRecommendation').value=`It is recommended that the assigned case manager validate the generated household information, update missing socioeconomic and SWDI details, confirm the status of all monitored members, and prepare an appropriate intervention plan based on verified needs. Continue or adjust program support in accordance with current DSWD policies and the results of case assessment.`;renderCsr()}
function clearCsr(){csrHousehold=null;$('csrHhid').value='';$('csrLookupStatus').textContent='';['csrProblem','csrBackground','csrAssessment','csrRecommendation'].forEach(id=>$(id).value='');$('csrPaper').innerHTML='<div class="empty">Enter a Household ID to generate the report.</div>'}
function interventionRows(h){const rows=[];if(h[6].includes('Education follow-up'))rows.push(['Education','Validate school attendance and barriers','Coordinate with school and conduct home visit','Case Manager, Household, School','Within 30 days','Attendance status validated']);if(h[6].includes('Pregnancy monitoring'))rows.push(['Maternal health','Ensure access to prenatal care','Refer to RHU and monitor compliance','Case Manager, Household, RHU','Immediate / ongoing','Prenatal services accessed']);if(h[6].includes('PWD member'))rows.push(['Disability support','Validate disability needs and benefits','Assess and refer to PDAO/LGU services','Case Manager, Household, LGU','Within 30 days','Appropriate referral completed']);if(h[6].includes('Locate / validate'))rows.push(['Household location','Validate current residence and membership','Conduct verification and coordinate with barangay','Case Manager, Barangay','Within 15 days','Household status updated']);if(!rows.length)rows.push(['Household well-being','Validate current needs and program compliance','Conduct case interview/home visit and update records','Case Manager, Household','Within 30 days','Current case information established']);return rows}
function renderCsr(){if(!csrHousehold)return;const h=csrHousehold,date=$('csrDate').value?new Date($('csrDate').value+'T00:00:00').toLocaleDateString('en-PH',{day:'2-digit',month:'long',year:'numeric'}):'',grantee=h[5]||'Not tagged',ip=uniq(h[7].map(m=>m[14])).join(', ')||'Not indicated',members=h[7].map(m=>`<tr><td>${esc(m[0])}</td><td>${esc(m[3])}</td><td>${esc(m[16]||'Not recorded')}</td><td>${esc(m[2])}</td><td>${esc(m[17]||'Not recorded')}</td><td>${esc(m[1])}</td><td>${esc(m[8]||m[18]||'Not recorded')}</td><td>For validation</td><td>For validation</td><td>${Number(m[2])>=60?'Senior Citizen':m[11]||'—'}</td><td>${esc(m[5]&&m[5]!=='NO'?'Child beneficiary':'—')}</td></tr>`).join(''),plans=interventionRows(h).map(r=>`<tr>${r.map(x=>`<td>${esc(x)}</td>`).join('')}<td>For review</td></tr>`).join('');$('csrPaper').innerHTML=`<div class="right">4Ps UNO KU Form 3</div><h1>SOCIAL CASE STUDY REPORT</h1><p class="right"><b>Date:</b> ${esc(date)}</p><h2>Identifying Information</h2><table class="meta"><tr><td>Grantee Name</td><td>${esc(grantee)}</td></tr><tr><td>Household ID No.</td><td>${esc(h[0])}</td></tr><tr><td>Household Set</td><td>${esc(h[1])}</td></tr><tr><td>Present Address</td><td>${esc(h[4])}, San Fabian, Pangasinan</td></tr><tr><td>IP Affiliation</td><td>${esc(ip)}</td></tr><tr><td>HH's Level of Well-being</td><td>For case-manager validation / SWDI record review</td></tr><tr><td>HH Risk Level Category</td><td>${esc(h[6].join(', ')||'No automated flag')}</td></tr></table><h2>Family Composition</h2><table><thead><tr><th>Name</th><th>Sex</th><th>Date of Birth</th><th>Age</th><th>Civil Status</th><th>Relationship</th><th>Education</th><th>Occupation</th><th>Monthly Income</th><th>Sector</th><th>Remarks</th></tr></thead><tbody>${members}</tbody></table><div class="validation"><b>Case-manager validation required:</b> Occupation, income, SWDI level, contact information, religion, housing, livelihood, and current circumstances are not established by the roster extract.</div><h2>Presenting Problem</h2><p>${esc($('csrProblem').value)}</p><h2>Background Information</h2><p>${esc($('csrBackground').value)}</p><h2>Assessment</h2><p>${esc($('csrAssessment').value)}</p><h2>Household Intervention Plan</h2><p><b>Overall Goal:</b> To strengthen household functioning and support progress toward an improved level of well-being based on verified needs.</p><table><thead><tr><th>Area of concern</th><th>Specific objectives</th><th>Activities</th><th>Responsible Person</th><th>Timeframe</th><th>Expected Results</th><th>Remarks</th></tr></thead><tbody>${plans}</tbody></table><h2>Recommendation</h2><p>${esc($('csrRecommendation').value)}</p><div class="csr-signatures"><div>Concurred by:<br><br>_______________________<br>Household Grantee/Head</div><div>Prepared by:<br><br><b>${esc($('csrManager').value)}</b><br>Name of Case Manager<br>Date: ${esc(date)}</div><div>Reviewed by:<br><br><b>RAIN CIARA C. BANZUELA</b><br>Name of SWO III<br>Date: ____________</div><div>Noted by:<br><br><b>EVAFE L. TERTE</b><br>Name of Provincial Link<br>Date: ____________</div></div>`}
function downloadCsrWord(){if(!csrHousehold){$('csrLookupStatus').textContent='Find a household first.';return}renderCsr();const css='body{font:10pt Arial}h1{text-align:center;font-size:14pt}h2{font-size:10.5pt;text-decoration:underline}p{text-align:justify;line-height:1.4}table{width:100%;border-collapse:collapse;font-size:8pt}th,td{border:1px solid #333;padding:4px}.right{text-align:right}.validation{background:#fff7dd;border:1px solid #c9a94d;padding:7px}.csr-signatures{margin-top:25px}',html=`<html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:w="urn:schemas-microsoft-com:office:word"><head><meta charset="utf-8"><style>${css}</style></head><body>${$('csrPaper').innerHTML}</body></html>`,a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff'+html],{type:'application/msword'}));a.download=`SCSR_${csrHousehold[0]}_${(csrHousehold[5]||'Household').replace(/[^a-z0-9]+/gi,'_')}.doc`;a.click();URL.revokeObjectURL(a.href)}
