function ensureBusView(){const view=document.createElement('section');view.className='view';view.id='view-bus';view.innerHTML=`<div class="bus-layout"><aside class="panel bus-form"><div><h2>Beneficiary Data Update Request</h2><p class="sub">BUS Form 5 V.2.2017 · Long form</p></div><div><label>Household ID number</label><div class="toolbar"><input id="busHhid" placeholder="Enter complete or partial HHID"><button class="btn primary" onclick="findBusHousehold()">Find</button></div><small id="busLookupStatus"></small></div><div><label>Name of grantee</label><input id="busGrantee" readonly></div><div><label>Date filed</label><input id="busDate" type="date" onchange="renderBusForm()"></div><div><label>Type of update</label><select id="busType" onchange="updateBusType()">${Object.entries(busTypes).map(([n,x])=>`<option value="${n}">${n}. ${x[0]}</option>`).join('')}</select></div><div><label>Name of affected member (leave blank when not applicable)</label><input id="busMember" oninput="renderBusForm()"></div><div><label>Field being updated</label><input id="busField" oninput="renderBusForm()"></div><div><label>From</label><input id="busFrom" oninput="renderBusForm()"></div><div><label>To</label><input id="busTo" oninput="renderBusForm()"></div><div><label>Reason / explanation</label><textarea id="busReason" rows="4" oninput="renderBusForm()"></textarea></div><div><label>Supporting documents</label><textarea id="busDocs" rows="3" oninput="renderBusForm()"></textarea></div><div><label>DSWD personnel / designation</label><input id="busPersonnel" oninput="renderBusForm()"></div><div class="bus-actions"><button class="btn primary" onclick="downloadBusWord()">Download Word (.doc)</button><button class="btn" onclick="window.print()">Print / Save PDF</button><button class="btn" onclick="clearBusForm()">Clear</button></div><div class="csr-hint"><b>Data rule:</b> Only grantee and household address details are auto-filled. Member-specific update fields remain blank until intentionally entered and verified.</div></aside><section class="bus-preview"><div id="busPaper"><div class="bus-page"><div class="empty">Enter a Household ID to generate BUS Form 5.</div></div></div></section></div>`;document.querySelector('main.shell').insertBefore(view,document.querySelector('main.shell footer'))}
