function busPageTwo(){const rows=Object.entries(busTypes).map(([n,x])=>`<tr><td>${n}. ${esc(x[0])}</td><td>${esc(x[1])}</td></tr>`).join('');return `<section class="bus-page"><div class="bus-band">CONTINUATION OF DATA CHANGE/CORRECTION/UPDATING</div><div class="bus-update"><h2>Only the selected update section should be completed</h2><p><b>Affected member:</b> <span class="bus-line">${esc($('busMember').value)}</span></p><p><b>Requested correction/update:</b> <span class="bus-line">${esc($('busField').value)}</span></p><p><b>From:</b> <span class="bus-line">${esc($('busFrom').value)}</span> &nbsp; <b>To:</b> <span class="bus-line">${esc($('busTo').value)}</span></p><p><b>Reason:</b> ${esc($('busReason').value)}</p><div style="height:55mm"></div><div class="bus-sign">Signature Over Printed Name of Grantee</div></div><div class="bus-band">PART II - TO BE FILLED OUT BY THE CBDO AND ENCODER</div><div class="bus-part2"><table><tr><td>Reviewed by:<br><br>Date Reviewed:<br><br>POO Remarks:</td><td>Encoded by:<br><br>Date Encoded:<br><br>Remarks of Encoder:</td></tr></table><p><b>IF NOT ENCODED:</b> ☐ Lacking/inconsistent documents &nbsp; ☐ Facility verification required &nbsp; ☐ Not in family roster &nbsp; ☐ Others</p></div><table class="bus-support"><thead><tr><th>TYPES OF UPDATES</th><th>SUPPORTING DOCUMENTS</th></tr></thead><tbody>${rows}</tbody></table></section>`}
