function schoolCopyHtml(){const h=schoolHousehold,type=$('schoolType').value,level=$('schoolLevel').value,year=$('schoolYear').value||'20__ - 20__';return `<section class="school-copy"><img class="school-header" src="${SCHOOL_HEADER}" alt="DSWD, DepEd and Pantawid Pamilyang Pilipino Program - School Enrolment Certificate"><div class="school-fields"><label>Household ID No.:</label><div class="school-line wide">${esc(h[0])}</div><label>Name of Grantee:</label><div class="school-line wide">${esc(h[5])}</div><label>Name of School:</label><div class="school-line">${esc($('schoolName').value)}</div><label>School ID#</label><div class="school-line">${esc($('schoolId').value)}</div><label>School Address:</label><div class="school-line wide">${esc($('schoolAddress').value)}</div></div><div class="school-options"><b>Type of School:</b><span>${schoolMark(type,'Private')} Private</span><span>${schoolMark(type,'Public')} Public</span><b>School Level:</b><span>${schoolMark(level,'Day Care')} Day Care (Child Dev't Centers)</span><span>${schoolMark(level,'Pre School')} Pre School</span><span></span><span>${schoolMark(level,'Elementary')} Elementary (Kinder - Grade 6)</span><span>${schoolMark(level,'Secondary')} Secondary (Junior & Senior High)</span><span></span><span>${schoolMark(level,'Higher Education')} Higher Education Institutions (HEIs)</span><span>${schoolMark(level,'Technical Vocational')} Technical Vocational Institutions (TVIs)</span></div><p class="school-cert-text">This is to certify that the following children are enrolled in this School for the School Year <b>${esc(year)}</b>:</p><table class="school-table"><thead><tr><th>Learners Reference Number (LRN)</th><th>NAME</th><th>AGE</th><th>GRADE LEVEL<br><small>(Day Care, Kinder, Grade 1-12, ALS/ADM, SPED)</small></th></tr></thead><tbody>${'<tr><td>&nbsp;</td><td></td><td></td><td></td></tr>'.repeat(5)}</tbody></table><div class="school-signatures"><div>${esc($('schoolDate').value)||'mm/dd/yyyy'}<br>Date Signed/Issued</div><div>${esc($('schoolSignatory').value)||'Signature over Printed Name'}</div><div>${esc($('schoolPosition').value)||'Position'}</div></div></section>`}
