const _renderHealthCert=renderHealthCert;renderHealthCert=function(){_renderHealthCert();if(!healthHousehold)return;document.querySelectorAll('#healthPaper .health-copy').forEach(copy=>{const marks=copy.querySelectorAll('.health-mark');if(marks[0])marks[0].outerHTML=`<img class="official-logo" src="${DSWD_LOGO}" alt="DSWD logo" width="48" height="42">`;if(marks[1])marks[1].outerHTML=`<img class="official-logo" src="${FOURPS_LOGO}" alt="4Ps logo" width="48" height="42">`})};
const _renderBusForm=renderBusForm;renderBusForm=function(){_renderBusForm();if(!busHousehold)return;const head=document.querySelector('#busPaper .bus-head');if(head&&!head.querySelector('img'))head.insertAdjacentHTML('afterbegin',`<img class="bus-logo dswd" src="${DSWD_LOGO}" alt="DSWD logo" width="65" height="38"><img class="bus-logo fourps" src="${FOURPS_LOGO}" alt="4Ps logo" width="65" height="38">`)};
const _renderCsr=renderCsr;renderCsr=function(){_renderCsr();if(!csrHousehold)return;const paper=$('csrPaper');if(!paper.querySelector('.csr-logo-row'))paper.insertAdjacentHTML('afterbegin',`<div class="csr-logo-row"><img src="${DSWD_LOGO}" alt="DSWD logo" width="48" height="42"><span></span><img src="${FOURPS_LOGO}" alt="4Ps logo" width="48" height="42"></div>`)};
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeProfile()});init();
